import{c as r,Q as a,j as t,m as s}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"HydraServe: Minimizing Cold Start Latency for Serverless LLM Serving in Public Clouds","description":"","frontmatter":{"url":"https://arxiv.org/abs/2502.15524","title":"HydraServe: Minimizing Cold Start Latency for Serverless LLM Serving in Public Clouds","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2502.15524,"authors":["Chiheng Lou","Sheng Qi","Chao Jin","Dapeng Nie","Haoran Yang","Yu Ding","Xuanzhe Liu","Xin Jin (Peking University + Alibaba Group)"],"pdf_path":"pdfs/2502.15524.pdf","published_date":"2025-09-25T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-02-21-hydraserve-cold-start-serverless-llm-2502-15524.md","filePath":"research/papers/2025-02-21-hydraserve-cold-start-serverless-llm-2502-15524.md","lastUpdated":1785909234000}'),i={name:"research/papers/2025-02-21-hydraserve-cold-start-serverless-llm-2502-15524.md"};function n(o,e,l,c,d,g){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="hydraserve-—-minimizing-cold-start-latency-for-serverless-llm-serving" tabindex="-1">HydraServe — Minimizing Cold Start Latency for Serverless LLM Serving <a class="header-anchor" href="#hydraserve-—-minimizing-cold-start-latency-for-serverless-llm-serving" aria-label="Permalink to &quot;HydraServe — Minimizing Cold Start Latency for Serverless LLM Serving&quot;">​</a></h1><h2 id="核心問題" tabindex="-1">核心問題 <a class="header-anchor" href="#核心問題" aria-label="Permalink to &quot;核心問題&quot;">​</a></h2><p>公有雲 serverless LLM serving 的 cold start latency 嚴重：生產環境 <strong>冷啟動 instance 首 token &gt;40 秒</strong>，而後續每 token 僅 ~30ms。兩大挑戰：(1) LLM 需從遠端 registry 按需抓取大型 model weights，受限頻寬成為主瓶頸；(2) LLM runtime 高度複雜（CUDA runtime、AI frameworks、inference engines 多層相依），container 建立與 library loading 開銷大。</p><h2 id="方法-4-個機制" tabindex="-1">方法（4 個機制） <a class="header-anchor" href="#方法-4-個機制" aria-label="Permalink to &quot;方法（4 個機制）&quot;">​</a></h2><ol><li><strong>Proactive model distribution</strong>：跨 server 分散 model，讓 worker 可快速 fetch</li><li><strong>Overlap cold-start stages</strong>：在 worker 內重疊冷啟動各階段（fetch / load / profile / prefill），減少串行等待</li><li><strong>Strategic GPU placement</strong>：分散 cold-start instance 避免網路爭用</li><li><strong>Pipeline consolidation</strong>：合併 worker group 為單一 serving endpoint，降低冷啟動資源消耗</li></ol><h2 id="關鍵數字" tabindex="-1">關鍵數字 <a class="header-anchor" href="#關鍵數字" aria-label="Permalink to &quot;關鍵數字&quot;">​</a></h2><ul><li>Cold start latency 降低 <strong>1.7×–4.7×</strong></li><li>SLO attainment 改善 <strong>1.43×–1.74×</strong>（vs baselines）</li></ul><h2 id="對-cc-workspace-的遷移啟示" tabindex="-1">對 cc-workspace 的遷移啟示 <a class="header-anchor" href="#對-cc-workspace-的遷移啟示" aria-label="Permalink to &quot;對 cc-workspace 的遷移啟示&quot;">​</a></h2><ul><li><strong>Overlap stages</strong> → SessionStart hook 串行 spawn（session-init 592ms + 其他）可改並行/async（<code>async: true</code>）</li><li><strong>Proactive distribution / pre-warm</strong> → prompt cache pre-warming（<code>max_tokens:0</code>）保持 cache 暖態</li><li>核心類比：冷啟動延遲可由<strong>架構重疊與預備</strong>消除，而非僅靠縮減載入量</li></ul>',9)])])}const m=r(i,[["render",n]]);export{p as __pageData,m as default};
